import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define a fused custom CUDA kernel that applies clamp, multiplies by multiplier,
# and performs max-reduction across the channel dimension (dim=1).
fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Kernel to clamp values, multiply by channel-wise multiplier, and reduce by max across channels.
__global__ void clamp_mul_max_kernel(
    const float* __restrict__ x,
    const float* __restrict__ multiplier,
    float* __restrict__ out,
    int N, int C, int D, int H, int W,
    float clamp_min, float clamp_max)
{
    // Grid dimensions: (N, D, H), block dimension: (W)
    int n = blockIdx.x; 
    int d = blockIdx.y;
    int h = blockIdx.z;
    int w = threadIdx.x;
    if (w >= W) return;

    float max_val = -3.402823e38f;  // FLT_MIN or a very negative number
    // Loop over channels to find the max after clamp and multiplication
    for (int c = 0; c < C; ++c) {
        // Index for input tensor x of shape [N, C, D, H, W]
        int idx_in = (((n * C + c) * D + d) * H + h) * W + w;
        float val = x[idx_in];

        // Clamp
        if (val < clamp_min) val = clamp_min;
        if (val > clamp_max) val = clamp_max;

        // Multiply by the channel-wise multiplier
        val *= multiplier[c];

        // Track max
        if (val > max_val) {
            max_val = val;
        }
    }

    // Index for output tensor out of shape [N, D, H, W]
    int idx_out = (((n) * D + d) * H + h) * W + w;
    out[idx_out] = max_val;
}

// C++ function wrapper
torch::Tensor clamp_mul_max_cuda(
    torch::Tensor x,
    torch::Tensor multiplier,
    float clamp_min,
    float clamp_max)
{
    // x shape: [N, C, D, H, W]
    // multiplier shape: [C]
    // Out shape: [N, D, H, W]

    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t D = x.size(2);
    int64_t H = x.size(3);
    int64_t W = x.size(4);

    auto out = torch::zeros({N, D, H, W}, x.options());

    dim3 blocks(N, D, H);
    dim3 threads(std::min((int64_t)1024, W));

    clamp_mul_max_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        clamp_min, clamp_max
    );

    return out;
}
"""

# C++ header declaration for the function
fused_cpp_source = """
torch::Tensor clamp_mul_max_cuda(torch::Tensor x,
                                 torch::Tensor multiplier,
                                 float clamp_min,
                                 float clamp_max);
"""

# Build the extension
fused_extension = load_inline(
    name="fused_extension",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["clamp_mul_max_cuda"],
    verbose=False,
)

# Optimized model with custom fused kernel
class ModelNew(nn.Module):
    """
    A 3D convolutional layer followed by multiplication, instance normalization,
    and a custom fused CUDA kernel that performs clamping, multiplication,
    and max-reduction across the channel dimension in a single pass.
    """
    def __init__(self, in_channels, out_channels, kernel_size, multiplier_shape, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        self.instance_norm = nn.InstanceNorm3d(out_channels)
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

    def forward(self, x):
        x = self.conv(x)
        # First multiplication with self.multiplier
        x = x * self.multiplier
        x = self.instance_norm(x)
        # Fused clamp, multiply, and max across channel dimension
        # Reshape multiplier to [out_channels] for kernel usage
        x = fused_extension.clamp_mul_max_cuda(
            x, self.multiplier.view(-1), self.clamp_min, self.clamp_max
        )
        return x
